import { createRequestHandler } from "@react-router/express";
import express from "express";
import { Readable } from "node:stream";
import path from "node:path";
import { fileURLToPath } from "node:url";

// The server build is generated by `react-router build` and carries no types.
const buildPath = new URL("./build/server/index.js", import.meta.url).href;
type ServerBuild = Parameters<typeof createRequestHandler>[0]["build"];
const build = (await import(buildPath)) as ServerBuild;

const root = path.dirname(fileURLToPath(import.meta.url));
const clientDir = path.join(root, "build/client");
const port = Number(process.env.PORT ?? 3001);
const host = process.env.HOST;

// The browser always calls /api same-origin. In the composed deployment Caddy
// routes those requests to the API before they reach this server; here we proxy
// them so `npm start --workspace web` is self-contained.
const apiUrl = process.env.API_URL ?? "http://127.0.0.1:3000";

const app = express();
app.disable("x-powered-by");

app.use("/api", async (req, res) => {
  try {
    const headers = new Headers();
    for (const [name, value] of Object.entries(req.headers)) {
      if (
        value === undefined ||
        name === "host" ||
        name === "connection" ||
        name === "content-length"
      ) {
        continue;
      }
      headers.set(name, Array.isArray(value) ? value.join(", ") : value);
    }

    const upstream = await fetch(new URL(req.originalUrl, apiUrl), {
      method: req.method,
      headers,
      redirect: "manual",
    });

    res.status(upstream.status);
    upstream.headers.forEach((value, name) => {
      if (
        name === "content-encoding" ||
        name === "content-length" ||
        name === "connection" ||
        name === "transfer-encoding"
      ) {
        return;
      }
      res.setHeader(name, value);
    });

    if (upstream.body) {
      Readable.fromWeb(
        upstream.body as unknown as import("node:stream/web").ReadableStream,
      ).pipe(res);
    } else {
      res.end();
    }
  } catch (error) {
    console.error("[web] API proxy failed", error);
    res.status(502).type("text/plain").send("Bad Gateway");
  }
});

app.use(
  "/assets",
  express.static(path.join(clientDir, "assets"), {
    immutable: true,
    maxAge: "1y",
  }),
);
app.use(express.static(clientDir));
app.use("/.well-known", express.static(path.join(clientDir, ".well-known")));

app.all(
  "/{*splat}",
  createRequestHandler({
    build,
    mode: process.env.NODE_ENV ?? "production",
  }),
);

const onListen = () => {
  console.log(`[web] http://localhost:${port}`);
};

const server = host
  ? app.listen(port, host, onListen)
  : app.listen(port, onListen);

for (const signal of ["SIGTERM", "SIGINT"] as const) {
  process.once(signal, () => server.close());
}
